class Solution:
    def largestEvenNumber(self, s: str) -> str:
        j = s.rfind('2')
        return s[:j + 1] if j != -1 else ""

c.cpp:
class Solution {
public:
    string largestEvenNumber(string s) {
        auto pos = s.rfind('2');
        return pos == string::npos ? string() : s.substr(0, pos + 1);
    }
};

