c.python:
class Solution:
    def largestEvenNumber(self, s: str) -> str:
        i = len(s) - 1
        while i >= 0 and s[i] == '1':
            i -= 1
        return s[:i + 1]

c.cpp:
class Solution {
public:
    string largestEvenNumber(string s) {
        int i = (int)s.size() - 1;
        while (i >= 0 && s[i] == '1') i--;
        return s.substr(0, i + 1);
    }
};

c.java:
class Solution {
    public String largestEvenNumber(String s) {
        int i = s.length() - 1;
        while (i >= 0 && s.charAt(i) == '1') i--;
        return s.substring(0, i + 1);
    }
}

